    const v = roundCents((afterBulkDiscount * (line.vatRate ?? 0)) / 100);

    subtotal += lt;
    discount += disc + bulkDisc;
    vat += v;
  }

  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);

  return {
    subtotal,
    discount,
    vat,
    voucher,
    total,
  };
}

