import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);

  const line1 = result.value.lines[0];
  assert.equal(line1.sku, 'DES-HOUR');
  assert.equal(line1.name, 'Design work (hour)');
  assert.equal(line1.qty, 5);
  assert.equal(line1.unitPrice, 8500);
  assert.equal(line1.vatRate, 21);

  const line2 = result.value.lines[1];
  assert.equal(line2.sku, 'DEV-HOUR');
  assert.equal(line2.name, 'Development (hour)');
  assert.equal(line2.qty, 3);
  assert.equal(line2.unitPrice, 9500);
  assert.equal(line2.vatRate, 21);
});

test('createInvoice normalizes customer ID (lowercase)', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID (with spaces)', () => {
  const result = createInvoice({
    customerId: ' C-001 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice normalizes customer ID (mixed case and spaces)', () => {
  const result = createInvoice({
    customerId: ' c-007 ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
});

test('createInvoice defaults terms to NET30', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31');
});

test('createInvoice rejects unknown terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'INVALID',
  });

  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice EOM handles different months', () => {
  const feb = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(feb.ok, true);
  assert.equal(feb.value.dueDate, '2026-02-28');

  const apr = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-04-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(apr.ok, true);
  assert.equal(apr.value.dueDate, '2026-04-30');
});

test('createInvoice NET30 spans months', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.dueDate, '2026-11-14');
});

test('applyVoucher applies voucher to draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
  };

  const result = applyVoucher(invoice, { code: 'SAVE10', amount: 5000 });
  assert.equal(result.ok, true);
  assert.deepEqual(result.value.voucher, { code: 'SAVE10', amount: 5000 });
});

test('applyVoucher rejects if voucher already applied', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 }],
    voucher: { code: 'EXISTING', amount: 1000 },
  };

  const result = applyVoucher(invoice, { code: 'NEW', amount: 5000 });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'VOUCHER_EXISTS');
});

test('applyVoucher rejects on issued invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
