test('invoiceTotals handles mixed VAT exempt and taxable items', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 42500 + 3700 + 60000;
  // Line 2 has qty=100, so bulk discount applies: 3700 * 2.5 / 100 = 92.5 -> 92
  // Line 2 VAT is on 3700 - 92 = 3608, so VAT = 3608 * 0.09 = 324.72 -> 325
  const vat = 8925 + 325 + 0;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, 92);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - 92 + vat);
});

