test('invoiceTotals with complex scenario', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 6 },
    ],
    voucher: { code: 'SUMMER', amount: 5000 },
  };
  const result = invoiceTotals(invoice);
  // Line 1: 10*10000=100000, line_disc=5000, after_line=95000, bulk_disc=95000*2.5/100=2375, after_bulk=92625, vat=92625*21/100=19451
  // Line 2: 5*2000=10000, line_disc=0, after_line=10000, bulk_disc=0, after_bulk=10000, vat=10000*6/100=600
  // Total discount = 5000 + 2375 = 7375
  // Total VAT = 19451 + 600 = 20051
  // Total = 100000 + 10000 - 7375 + 20051 - 5000 = 117676
  assert.equal(result.subtotal, 110000);
  assert.equal(result.discount, 7375);
  assert.equal(result.vat, 20051);
  assert.equal(result.voucher, 5000);
  assert.equal(result.total, 117676);
