test('invoiceTotals sums VAT from multiple lines with different rates and discounts', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 5 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 42500 + 3700 + 60000;
  // Line 1: discount = 4250, no bulk discount (qty < 10)
  // Line 2: discount = 185 + 88 (line discount + bulk discount), bulk = 3515 * 2.5 / 100 = 87.875 -> 88
  // Line 3: discount = 0
  const discount1 = 4250;
  const discount2 = 185 + 88;
  const totalDiscount = discount1 + discount2;
  // Line 1: VAT = (42500 - 4250) * 21 / 100 = 38250 * 21 / 100 = 8032.5 -> 8033 (banker's rounding)
  // Line 2: VAT = (3700 - 185 - 88) * 9 / 100 = 3427 * 9 / 100 = 308.43 -> 308 (banker's rounding)
  // Line 3: VAT = 0
  const vat1 = 8033;
  const vat2 = 308;
  const vat3 = 0;
  const totalVat = vat1 + vat2 + vat3;

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, totalDiscount);
  assert.equal(totals.vat, totalVat);
  assert.equal(totals.total, subtotal - totalDiscount + totalVat);
});

