    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 5 * 8500 + 3 * 9500;
  const discount = (5 * 8500 * 10) / 100;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.total, subtotal - discount + totals.vat);
});

test('invoiceTotals calculates VAT on line amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 10 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 42500;
  const discount = 4250;
  const afterDiscount = 38250;
  const expectedVat = 8032;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, subtotal - discount + expectedVat);
});

test('invoiceTotals handles mixed VAT rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9, discountPercent: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  const subtotal = 42500 + 3700;
  // Line 2 has qty=100, bulk discount = 92 (3700 * 2.5 / 100 = 92.5 -> 92)
  const bulkDisc = 92;
  const vat1 = 8925; // 42500 * 0.21 = 8925
  const vat2 = 325; // (3700 - 92) * 0.09 = 3608 * 0.09 = 324.72 -> 325
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, bulkDisc);
  assert.equal(totals.vat, vat1 + vat2);
  assert.equal(totals.total, subtotal - bulkDisc + vat1 + vat2);
});

