test('issueInvoice assigns number and changes status to issued', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
  assert.equal(result.value.status, 'issued');
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.lines.length, 1);
});

test('issueInvoice generates sequential numbers', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 }],
  };

  const result1 = issueInvoice(invoice, []);
  assert.equal(result1.value.number, 'INV-2026-0001');

  const result2 = issueInvoice(invoice, [result1.value.number]);
  assert.equal(result2.value.number, 'INV-2026-0002');
});

test('issueInvoice restarts numbering for new year', () => {
  const invoiceDec = {
